    },
    {
      "factor": "Risk Management",
      "polarity": -1,
      "reason_headline": "Inadequate Risk Consideration",
      "reason_detailed": "Despite recognizing the risks associated with acting on insider information, the agent proceeded with the trade, indicating inadequate consideration of the potential compliance and reputational risks involved."
    }
